          value={name}
          onUpdate={setName}
          placeholder={t('form.name.placeholder')}
          hasClear
        />
      </Flex>
      <Flex direction="column" gap={1}>
        <Text variant="subheader-1" as="span" id="demo-fruit-label">
          {t('form.fruit.label')}
        </Text>
        <Select
          value={fruit}
          onUpdate={setFruit}
          options={fruitOptions}
          placeholder={t('form.fruit.placeholder')}
          hasClear
          width="max"
          controlProps={{ 'aria-labelledby': 'demo-fruit-label' }}
        />
      </Flex>
      <Flex gap={2}>
        <Button
          view="action"
          onClick={() => toaster.add({ name: 'saved', title: t('toast.saved'), theme: 'success' })}
        >
          {t('form.submit')}
        </Button>
        <Button
          view="outlined"
          onClick={() => {
            setName('');
            setFruit([]);
          }}
        >
          {t('form.reset')}
        </Button>
      </Flex>
    </Flex>
  );
}

function Content() {
  const { t, language } = useTranslation();
  const [page, setPage] = React.useState(1);
  const [pageSize, setPageSize] = React.useState(10);

  return (
    <Flex direction="column" gap={5} style={{ maxWidth: 720, margin: '0 auto', padding: 24 }}>
      <Flex direction="column" gap={2}>
        <Text variant="display-1" as="h1">
