          <SegmentedRadioGroup.Option key={lang} value={lang} qa={`language-option-${lang}`}>
            {LANGUAGE_LABELS[lang]}
          </SegmentedRadioGroup.Option>
        ))}
      </SegmentedRadioGroup>
    </div>
  );
}
