            setPage(nextPage);
            setPageSize(nextPageSize);
          }}
        />
      </Flex>
    </Flex>
  );
}

export function App() {
  return (
    <LanguageProvider>
      <ToasterProvider toaster={toaster}>
        <Content />
        <ToasterComponent />
      </ToasterProvider>
    </LanguageProvider>
  );
}
